import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"How are the datapoints structured and how do I write to them?","description":"","frontmatter":{"order":2,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/03.referenz/02.datenpunkte.md"},"headers":[],"relativePath":"adapter/esphome/referenz/datenpunkte.md","filePath":"adapter/esphome/referenz/datenpunkte.md","lastUpdated":1795571670000}'),n={name:"adapter/esphome/referenz/datenpunkte.md"};function i(s,e,c,h,r,p){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="how-are-the-datapoints-structured-and-how-do-i-write-to-them" tabindex="-1">How are the datapoints structured and how do I write to them? <a class="header-anchor" href="#how-are-the-datapoints-structured-and-how-do-i-write-to-them" aria-label="Permalink to &quot;How are the datapoints structured and how do I write to them?&quot;">​</a></h1><p><a id="datapoint-path-contain-number-instead"></a></p><h2 id="why-does-the-datapoint-path-contain-a-number-instead-of-the-sensor-name" tabindex="-1">Why does the datapoint path contain a number instead of the sensor name? <a class="header-anchor" href="#why-does-the-datapoint-path-contain-a-number-instead-of-the-sensor-name" aria-label="Permalink to &quot;Why does the datapoint path contain a number instead of the sensor name?&quot;">​</a></h2><p>The number is the key ESPHome gives the entity. The adapter builds every path like this:</p><p><code>esphome.0.&lt;device&gt;.&lt;type&gt;.&lt;key&gt;.&lt;state&gt;</code>, e.g. <code>esphome.0.A1B2C3D4E5F6.Sensor.1234567890.state</code></p><table tabindex="0"><thead><tr><th>Part</th><th>Content</th></tr></thead><tbody><tr><td><code>&lt;device&gt;</code></td><td>MAC address without colons</td></tr><tr><td><code>&lt;type&gt;</code></td><td>kind of entity, e.g. <code>Sensor</code>, <code>Switch</code>, <code>Light</code></td></tr><tr><td><code>&lt;key&gt;</code></td><td>key of the entity from the API</td></tr><tr><td><code>&lt;state&gt;</code></td><td>usually <code>state</code>, several for lights, covers and fans</td></tr></tbody></table><p>The tab &quot;Objects&quot; shows the readable name from the YAML in the column &quot;Name&quot; of the entity folder. The adapter cannot change the path. If you rename the entity in the YAML, ESPHome changes the key and the path becomes a new one. The adapter removes the old folder after the connection.</p><p>If you want fixed, readable names, create an alias.</p><p><strong>See also:</strong> <a href="./../anleitungen/automatisieren#use-esphome-datapoints-aliases-alexa">Create aliases</a> · <a href="./../anleitungen/geraete-verwalten#clean-up-devices-datapoints-no">Clean up old states</a></p><p><a id="online-status-wifi-signal-ip"></a></p><h2 id="where-do-i-find-online-status-wifi-signal-ip-and-uptime-of-a-device" tabindex="-1">Where do I find online status, WiFi signal, IP and uptime of a device? <a class="header-anchor" href="#where-do-i-find-online-status-wifi-signal-ip-and-uptime-of-a-device" aria-label="Permalink to &quot;Where do I find online status, WiFi signal, IP and uptime of a device?&quot;">​</a></h2><p>Whether a device is connected is shown by <code>esphome.0.&lt;device&gt;.info._online</code>: <code>true</code> while the connection stands, otherwise <code>false</code>. The state has the role <code>indicator.reachable</code>. The exact status, e.g. <code>unreachable</code> or <code>Encryption Key Missing</code>, is in <code>info._connectionStatus</code>.</p><p>For the whole instance there are two states:</p><table tabindex="0"><thead><tr><th>State</th><th>Content</th></tr></thead><tbody><tr><td><code>esphome.0.info.connection</code></td><td><code>true</code> while the adapter runs</td></tr><tr><td><code>esphome.0.info.connectedDevices</code></td><td>names of the connected devices, comma-separated. With the dashboard enabled, the list stays empty until the dashboard answers.</td></tr></tbody></table><p>ESPHome only reports Wi-Fi signal, IP address and uptime if they are sensors in the YAML, e.g. <code>wifi_signal</code>, <code>uptime</code> and <code>wifi_info</code>. They then appear under <code>Sensor</code> or <code>TextSensor</code> of the device. A <code>wifi_signal</code> sensor also shows the signal on the device card in the tab &quot;Devices&quot;.</p><p><a id="command-acknowledged-ack-happens-offline"></a></p><h2 id="when-is-a-command-acknowledged-ack-and-what-happens-with-an-offline-device" tabindex="-1">When is a command acknowledged (ack) and what happens with an offline device? <a class="header-anchor" href="#when-is-a-command-acknowledged-ack-and-what-happens-with-an-offline-device" aria-label="Permalink to &quot;When is a command acknowledged (ack) and what happens with an offline device?&quot;">​</a></h2><p>When you write a state, it first shows <code>ack = false</code>. The adapter sends the command to the device. The value is acknowledged (<code>ack = true</code>) only once the device reports its new state.</p><p>The device never reports some states back, they stay unacknowledged: <code>SET</code> of a button, <code>command</code> of a lock and <code>stop</code> of a cover. The adapter acknowledges <code>config.rgbAutoWhite</code> itself.</p><p>If the device is not connected, the adapter sends nothing. The value stays at <code>ack = false</code> and the log shows <code>[onStateChange] Device &lt;device&gt; is not connected, command &lt;state&gt; not sent</code>. This lets scripts see that the command did not arrive. Check <code>info._online</code> of the device then.</p><p><strong>See also:</strong> <a href="#online-status-wifi-signal-ip">Online status of a device</a></p>',21)])])}const f=t(n,[["render",i]]);export{m as __pageData,f as default};
